// Dragino LDS02 (porte) : décodeur officiel « lds01_02_Decoder_ttn_v1.5 » (trame de 10 octets).
// Batterie : 14 bits de poids faible des octets 0-1 (mV). Mode : octet 2 (1 = porte, 3 = porte + fuite).
// Porte ouverte : bit 7 de l'octet 0. Mode 1 : cumul des ouvertures (octets 3-5), durée de la dernière en min (6-8).
function decode(bytes, fPort) {
    if (bytes.length !== 10) return null;
    const u24 = o => (bytes[o] << 16) | (bytes[o + 1] << 8) | bytes[o + 2];
    const mode = bytes[2];
    const r = { mode, battery: ((bytes[0] << 8) | bytes[1]) & 0x3FFF };
    if (mode === 1 || mode === 3) r.door_open = (bytes[0] & 0x80) ? 1 : 0;
    if (mode === 1) { r.open_count = u24(3); r.last_open_min = u24(6); }
    return r;
}
function metrique(cle) {
    return cle === "door_open" ? [0, 0, ""] : null;
}

