const TABLE = "lwl02";
// Dragino LWL02 (fuite) : même décodeur officiel que le LDS02 (« lds01_02 », trame de 10 octets).
// Batterie : 14 bits de poids faible des octets 0-1 (mV). Mode : octet 2 (2 = fuite, 3 = porte + fuite).
// Fuite : bit 6 de l'octet 0. Mode 2 : cumul des fuites (octets 3-5), durée de la dernière en min (6-8).
function decode(bytes, fPort) {
    if (bytes.length !== 10) return null;
    const u24 = o => (bytes[o] << 16) | (bytes[o + 1] << 8) | bytes[o + 2];
    const mode = bytes[2];
    const r = { mode, battery: ((bytes[0] << 8) | bytes[1]) & 0x3FFF };
    if (mode === 2 || mode === 3) r.leak = (bytes[0] & 0x40) ? 1 : 0;
    if (mode === 2) { r.leak_count = u24(3); r.last_leak_min = u24(6); }
    return r;
}
function metrique(cle) {
    return cle === "leak" ? [0, 0, ""] : null;
}

