const TABLE = "se0x";
// Dragino SE01 à SE04 (sondes de sol) : décodeur officiel « SE0X-LB decoder ».
// Port 2 : batterie (14 bits, mV), DS18B20 en 1/10 °C (0x7FFF = absente), octet 4 : bit 7 = mode
// (0 = valeurs calibrées, 1 = brutes), bits 3..0 = sondes 1..4 présentes. Puis 6 octets par sonde présente :
// humidité (1/100 %), température (1/100 °C, signée), conductivité (µS/cm). Mode 1 : seules batterie et DS18B20.
function decode(bytes, fPort) {
    if (fPort !== 2 || bytes.length < 5) return null;
    const r = { mode: (bytes[4] >> 7) & 1, battery: ((bytes[0] << 8) | bytes[1]) & 0x3FFF };
    if (bytes.readUInt16BE(2) !== 0x7FFF) r.temperature = bytes.readInt16BE(2) / 10;
    if (r.mode === 0) {
        const presentes = bytes[4] & 0x0F;
        for (let i = 0, j = 0; i < 4; i++) {
            if (!((presentes >> (3 - i)) & 1)) continue;
            if (bytes.length < 11 + j) break;
            r[`soil${i + 1}_moisture`] = bytes.readUInt16BE(5 + j) / 100;
            r[`soil${i + 1}_temp`] = bytes.readInt16BE(7 + j) / 100;
            r[`soil${i + 1}_ec`] = bytes.readUInt16BE(9 + j);
            j += 6;
        }
    }
    return r;
}
function metrique(cle) {
    if (cle === "temperature" || /^soil\d_temp$/.test(cle)) return [-40, 85, "°C"];
    if (/^soil\d_moisture$/.test(cle)) return [0, 100, "%"];
    if (/^soil\d_ec$/.test(cle)) return [0, 20000, "µS/cm"];
    return null;
}

