const TABLE = "cpl03";
// Dragino CPL01 / CPL03 (contact sec, compteurs) : décodeur officiel « CPL03-LB_TTN_v1.1.1 ».
// Port 2, octet 0 bit 3 : 0 = mode CPL01 (contact : bit 0 = ouvert ; cumul d'impulsions octets 1-3 ;
// durée de la dernière ouverture en min, octets 4-6), 1 = mode CPL03 (3 compteurs : octets 1-3, 4-6, 7-9).
// Port 5 : batterie aux octets 5-6 (mV).
function decode(bytes, fPort) {
    if (fPort === 5 && bytes.length >= 7) return { battery: bytes.readUInt16BE(5) };
    if (fPort !== 2 || bytes.length < 10) return null;
    const u24 = o => (bytes[o] << 16) | (bytes[o + 1] << 8) | bytes[o + 2];
    if (bytes[0] & 0x08) return { mode: 3, pulse_pa8: u24(1), pulse_pa4: u24(4), pulse_pb15: u24(7) };
    return { mode: 1, contact_open: (bytes[0] & 0x01) ? 1 : 0, pulse_total: u24(1), last_duration_min: u24(4) };
}
function metrique(cle) {
    if (cle === "contact_open") return [0, 0, ""];
    if (/^pulse_/.test(cle)) return [0, 1000000000, ""];
    return null;
}

