// Garde chaque uplink tel quel (octets, port, compteur) dans public.uplinks :
// on pourra redécoder l'historique quand un décodeur gagne des colonnes. Requête paramétrée.
const up = msg.ttn && msg.ttn.uplink_message;
if (!up || !up.frm_payload) return null;
return {
    query: "INSERT INTO public.uplinks (time, tenant, name, application_id, f_port, f_cnt, frm_payload) "
         + "VALUES ($1, $2, $3, $4, $5, $6, decode($7, 'base64')) ON CONFLICT DO NOTHING",
    params: [up.received_at, msg.tenant, msg.devId, msg.appId, up.f_port ?? null, up.f_cnt ?? null, up.frm_payload]
};
